import{_ as t,o as r,c as o,aj as e}from"./chunks/framework.kB0W2StX.js";const _=JSON.parse('{"title":"Юрист в сфере строительства и девелопмента","description":"","frontmatter":{},"headers":[],"relativePath":"data/ai-construction-part13.md","filePath":"data/ai-construction-part13.md"}'),i={name:"data/ai-construction-part13.md"};function n(l,a,s,h,c,d){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="юрист-в-сфере-строительства-и-девелопмента" tabindex="-1">Юрист в сфере строительства и девелопмента <a class="header-anchor" href="#юрист-в-сфере-строительства-и-девелопмента" aria-label="Permalink to &quot;Юрист в сфере строительства и девелопмента&quot;">​</a></h1><h2 id="роль-и-задачи-в-современности" tabindex="-1">Роль и задачи в современности <a class="header-anchor" href="#роль-и-задачи-в-современности" aria-label="Permalink to &quot;Роль и задачи в современности&quot;">​</a></h2><p>Строительный юрист использует алгоритмы машинного обучения для моментального аудита огромных договоров генерального подряда, поиска скрытых юридических рисков и анализа судебной практики по спорам о сроках и качестве работ.</p><hr><h2 id="рекомендуемые-ии-инструменты" tabindex="-1">Рекомендуемые ИИ-инструменты <a class="header-anchor" href="#рекомендуемые-ии-инструменты" aria-label="Permalink to &quot;Рекомендуемые ИИ-инструменты&quot;">​</a></h2><ul><li><strong>Kira Systems / Luminance</strong> — ИИ-платформы для глубокого анализа договоров, которые автоматически находят нестандартные формулировки, штрафы и зоны риска.</li><li><strong>Pravo.ru AI / Справочные системы с ИИ</strong> — инструменты для быстрого анализа судебных дел, прогнозирования исхода строительных споров в арбитраже.</li><li><strong>ChatGPT / Claude</strong> — для составления протоколов разногласий, претензий и формулирования каучуковых (гибких) формулировок условий договоров.</li></ul><hr><h2 id="в-чем-конкретно-помогает-ии" tabindex="-1">В чем конкретно помогает ИИ <a class="header-anchor" href="#в-чем-конкретно-помогает-ии" aria-label="Permalink to &quot;В чем конкретно помогает ИИ&quot;">​</a></h2><ul><li><strong>Экспресс-аудит договоров:</strong> за несколько минут изучает 100-страничный договор подряда и подсвечивает «кабальные» пункты (например, скрытые штрафы за задержку документации или несимметричные условия расторжения).</li><li><strong>Сбор доказательной базы:</strong> помогает быстро сформулировать позицию для суда по взысканию долга с заказчика на основе писем, актов КС-2 и журналов работ.</li><li><strong>Мониторинг законодательства:</strong> отслеживает изменения в градостроительном кодексе, земельном праве и вовремя предупреждает об изменении регламентов выдачи разрешений на строительство.</li></ul><hr><h2 id="промты-для-работы" tabindex="-1">Промты для работы <a class="header-anchor" href="#промты-для-работы" aria-label="Permalink to &quot;Промты для работы&quot;">​</a></h2><h3 id="промт-для-проверки-пункта-договора-в-чат-бот" tabindex="-1">Промт для проверки пункта договора (в чат-бот) <a class="header-anchor" href="#промт-для-проверки-пункта-договора-в-чат-бот" aria-label="Permalink to &quot;Промт для проверки пункта договора (в чат-бот)&quot;">​</a></h3><blockquote><p>Я прикреплю текст раздела &quot;Ответственность сторон&quot; из договора строительного подряда. Проанализируй его с точки зрения защиты интересов Подрядчика. Подсвети пункты, где ответственность Подрядчика явно несоразмерна нарушениям, и перепиши эти пункты в более сбалансированной форме.</p></blockquote><h3 id="промт-для-составления-досудебнои-претензии" tabindex="-1">Промт для составления досудебной претензии <a class="header-anchor" href="#промт-для-составления-досудебнои-претензии" aria-label="Permalink to &quot;Промт для составления досудебной претензии&quot;">​</a></h3><blockquote><p>Действуй как опытный адвокат в строительной сфере. Напиши досудебную претензию от лица Генподрядчика к Заказчику о погашении задолженности за выполненные работы. Сумма долга: 14 500 000 рублей. Работы приняты без замечаний, акты КС-2 и КС-3 подписаны Заказчиком 45 дней назад, но оплата не поступила. Сошлись на статьи Гражданского кодекса о подряде и исполнении обязательств, укажи на начисление неустойки и намерение обратиться в Арбитражный суд.</p></blockquote>',15)])])}const p=t(i,[["render",n]]);export{_ as __pageData,p as default};
